import {evaluatePayment} from './core.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='scrim.workspace.v2', uid=()=>crypto.randomUUID(), now=()=>new Date().toISOString();
const initial=()=>({version:3,settings:{name:'',hide:false,expiry:30},policy:{dailyLimit:null,perPaymentLimit:null,approvalThreshold:null,approvedCounterparties:[],enabled:false,proofs:false},payments:[],proofs:[],batches:[],events:[]});
let state;try{state=JSON.parse(localStorage.getItem(KEY));if(state?.version!==3)state=initial()}catch{state=initial()}
let route='overview',filter='all',search='',submit;const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Browser storage is unavailable. Changes last only for this session.')}};
const money=n=>state.settings.hide?'••••••':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(n)||0);
const today=()=>new Date().toISOString().slice(0,10), spent=()=>state.payments.filter(p=>p.at.startsWith(today())&&!['rejected'].includes(p.status)).reduce((n,p)=>n+p.amount,0);
const reserved=()=>state.payments.filter(p=>p.status!=='rejected').reduce((n,p)=>n+p.amount,0)+state.batches.reduce((n,b)=>n+b.total,0);
const log=(action,detail)=>state.events.unshift({id:uid(),at:now(),action,detail});
const notify=(msg)=>{save();render();toast(msg)};let toastTimer;function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000)}
const paths={overview:'M3 3h6v6H3z M15 3h6v6h-6z M3 15h6v6H3z M15 15h6v6h-6z',payments:'M4 8h16m-5-5 5 5-5 5M20 16H4m5-5-5 5 5 5',treasury:'M3 8h18L12 3 3 8zm2 3v7m7-7v7m7-7v7M3 21h18',approvals:'m5 12 4 4L19 6M21 12v8H3V4h12',agents:'M6 7h12v12H6zM12 3v4M3 11h3m12 0h3M9 11v3m6-3v3M9 17h6',proofs:'M12 3 3 7v6c0 5 9 8 9 8s9-3 9-8V7l-9-4zm-4 9 3 3 5-6',activity:'M3 12h4l3-8 4 16 3-8h4',settings:'M4 7h16M4 17h16M8 4v6m8 4v6'};
const names={overview:'Overview',payments:'Payments',treasury:'Treasury',approvals:'Approvals',agents:'Agent controls',proofs:'Disclosures',activity:'Activity & exports',settings:'Settings'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]}"/></svg>`;
const button=(text,action,style='primary')=>`<button class="button ${style}" data-action="${action}">${text}</button>`;
function header(title,desc,actions=''){return `<div class="page-head"><div><span class="eyebrow">YOUR WORKSPACE / ${esc(names[route]).toUpperCase()}</span><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
const notice='<div class="notice">No wallet is connected. Records created here stay in this browser for interface testing only. Do not enter sensitive information.</div>';
const empty=(title,detail)=>`<div class="empty"><b>${title}</b>${detail}</div>`;
const status=p=>`<span class="status ${esc(p)}">${esc({awaiting:'Needs approval',ready:'Ready · simulated',rejected:'Rejected',draft:'Draft',expired:'Expired',revoked:'Revoked'}[p]||p)}</span>`;
function table(items){return items.length?`<div class="table-wrap"><table><thead><tr><th>COUNTERPARTY</th><th>AMOUNT</th><th>STATUS</th><th>CREATED</th></tr></thead><tbody>${items.map(p=>`<tr><td><div class="person"><span class="person-icon">↗</span><div><strong>${esc(p.to)}</strong><small>${esc(p.note||'Agent payment request')}</small></div></div></td><td class="mono">${money(p.amount)}<small>USDC · NEAR</small></td><td>${status(p.status)}</td><td>${new Date(p.at).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</td></tr>`).join('')}</tbody></table></div>`:empty('Your first payment starts here','Create a request to test policy checks and the approval flow.')}
function overview(){const configured=state.policy.dailyLimit&&state.policy.perPaymentLimit&&state.policy.approvedCounterparties.length;return header('Your private workspace.','Connect a wallet to begin using Scrim.',configured?button('↗ New payment','payment'):button('Set payment rules','agents'))+`<div class="overview-grid"><section class="balance-panel"><span class="eyebrow">TREASURY</span><div class="balance-total">—</div><div class="balance-caption">Connect a wallet to view balances and assets.</div><div class="balance-actions">${button('Wallet connection coming soon','noop','secondary')}</div></section><div class="insights"><section class="panel panel-pad"><span class="panel-label">AGENT POLICY</span><div class="budget-amount">${configured?'Configured':'Not configured'}</div><p class="muted">${configured?'Rules are saved locally in this browser.':'Set caps and approved counterparties before creating any payment requests.'}</p><a class="text-button" style="display:inline-block;margin-top:14px" href="#agents">Open agent controls →</a></section><section class="panel panel-pad"><div class="callout"><span class="callout-icon">⌁</span><div><h3>No account connected</h3><p>Wallet, custody, and settlement integrations are being built.</p></div></div></section></div></div><section class="panel"><div class="panel-header"><div><h3>Recent payments</h3><p>Records appear here after you create them.</p></div><a class="text-button" href="#payments">View all →</a></div>${table(state.payments.slice(0,5))}</section><div class="section-gap">${notice}</div>`}
function payments(){let rows=state.payments.filter(p=>(filter==='all'||p.status===filter)&&`${p.to} ${p.note}`.toLowerCase().includes(search.toLowerCase()));return header('Payments','One request. Clear permissions. A traceable decision.',button('↗ New payment','payment'))+`<div class="filters"><div class="tabs">${[['all','All requests'],['awaiting','Needs approval'],['ready','Ready'],['rejected','Rejected']].map(([id,label])=>`<button data-filter="${id}" class="${filter===id?'active':''}">${label}</button>`).join('')}</div><input class="search" aria-label="Search payments" placeholder="Search counterparties or notes" value="${esc(search)}" id="search"></div><section class="panel">${table(rows)}</section><div class="section-gap">${notice}</div>`}
function treasury(){return header('Treasury','Connect a wallet to view balances and prepare settlement.',button('+ Payroll draft','payroll'))+`<section class="panel panel-pad"><div class="empty"><b>No assets to show</b>Wallet balances will appear here after a connection is available.</div></section><section class="panel section-gap"><div class="panel-header"><div><h3>Payroll drafts</h3><p>Create a draft with your own recipients and amounts.</p></div></div>${state.batches.length?`<div class="table-wrap"><table><thead><tr><th>BATCH</th><th>RECIPIENTS</th><th>TOTAL</th><th>STATUS</th></tr></thead><tbody>${state.batches.map(b=>`<tr><td>${esc(b.name)}</td><td>${b.rows.length}</td><td>${money(b.total)}</td><td>${status('draft')}</td></tr>`).join('')}</tbody></table></div>`:empty('No payroll drafts','Add recipients and amounts to prepare your first batch.')}</section><div class="section-gap">${notice}</div>`}
function approvals(){let list=state.payments.filter(p=>p.status==='awaiting');return header('Every consequential move, reviewed.','Requests at or above your approval threshold appear here.')+`<div class="notice">Approval is a local interface preview. Independent signatures and on-chain enforcement are not connected.</div><div class="cards">${list.map(p=>`<article class="panel request"><div class="spread">${status(p.status)}<small>USDC / NEAR</small></div><h3>${esc(p.to)}</h3><p class="muted">${esc(p.note||'Payment request')}</p><div class="request-amount">${money(p.amount)}</div><div class="detail-list"><div><span>Requested by</span><b>Workspace</b></div><div><span>Approval threshold</span><b>${money(state.policy.approvalThreshold)}</b></div></div><div class="actions">${button('Simulate approval',`approve:${p.id}`)}${button('Reject',`reject:${p.id}`,'secondary')}</div></article>`).join('')}</div>${!list.length?`<section class="panel">${empty('No requests waiting','Requests requiring approval will appear here.')}</section>`:''}`}
const field=(label,name,value,type='text',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra} required></label>`;
function agents(){const p=state.policy;return header('Autonomy, with boundaries.','Set the rules that every agent payment request must pass.')+`<div class="policy-grid"><form id="policy-form" class="panel panel-pad"><div class="policy-title"><div class="person"><span class="person-icon">⌘</span><div><h3>Payment policy</h3><small>Stored locally until enforcement is connected</small></div></div><span class="status">${p.enabled?'Enabled':'Paused'}</span></div><div class="form-grid">${field('Daily cap · USDC','dailyLimit',p.dailyLimit??'','number','min="0.01" step="0.01"')}${field('Per-payment cap · USDC','perPaymentLimit',p.perPaymentLimit??'','number','min="0.01" step="0.01"')}${field('Approval required from · USDC','approvalThreshold',p.approvalThreshold??'','number','min="0.01" step="0.01"')}</div><label class="field">Approved counterparties<textarea name="approved" placeholder="payee.near">${esc(p.approvedCounterparties.join('\n'))}</textarea><small>One NEAR account per line. Requests to other accounts are blocked.</small></label><label class="rule"><div>Allow payment requests<small>Pause new requests without deleting the policy.</small></div><input type="checkbox" name="enabled" ${p.enabled?'checked':''}></label><label class="rule"><div>Allow disclosure drafts<small>Creates local draft statements only.</small></div><input type="checkbox" name="proofs" ${p.proofs?'checked':''}></label><p id="policy-error" class="error"></p><div class="section-gap"><button class="button primary">Save policy</button></div></form><section class="panel panel-pad"><span class="eyebrow">BEFORE A PAYMENT CAN PROCEED</span>${[['Check the counterparty','Only accounts on the allowlist may receive a request.'],['Check both spending limits','Pending requests count toward the daily budget.'],['Route for review','Amounts at or above the threshold need review.'],['Wait for settlement integration','Saved requests remain local. No funds leave this workspace.']].map(([h,p],i)=>`<div class="flow-step"><i>${i+1}</i><div><h3>${h}</h3><p>${p}</p></div></div>`).join('')}</section></div>`}
const proofState=p=>p.status==='revoked'?'revoked':Date.parse(p.expiresAt)<=Date.now()?'expired':'draft';
function proofs(){return header('Disclose a fact. Keep the context.','Prepare a reader-bound statement with a limited access window.',button('+ New disclosure','proof'))+`<div class="notice">These are editable local disclosure drafts, not cryptographic proofs. Expiry changes draft status; it cannot erase information already seen or copied by a reader.</div><div class="cards">${state.proofs.map(p=>`<article class="panel request"><div class="spread"><span class="panel-label">${esc(p.type)}</span>${status(proofState(p))}</div><h3>${esc(p.fact)}</h3><div class="detail-list"><div><span>Named reader</span><b>${esc(p.reader)}</b></div><div><span>Expires</span><b>${new Date(p.expiresAt).toLocaleString()}</b></div></div>${proofState(p)==='draft'?button('Revoke draft',`revoke:${p.id}`,'secondary'):''}</article>`).join('')}</div>${!state.proofs.length?`<section class="panel">${empty('Share less. Start with one fact.','Choose a statement, name the reader, and set the expiry.')}</section>`:''}`}
function activity(){return header('A record of every decision.','Review local actions and export the workspace for inspection.',button('↓ Export JSON','export'))+`<div class="notice">Exports contain plaintext sandbox records, including recipients and amounts. They are not encrypted or independently attested audit evidence.</div><section class="panel"><div class="panel-header"><h3>Workspace activity</h3><small>${state.events.length} events</small></div>${state.events.length?`<div class="table-wrap"><table><thead><tr><th>ACTION</th><th>DETAIL</th><th>TIME</th></tr></thead><tbody>${state.events.map(e=>`<tr><td>${esc(e.action)}</td><td>${esc(e.detail)}</td><td>${new Date(e.at).toLocaleString()}</td></tr>`).join('')}</tbody></table></div>`:empty('A clean slate','Saved actions will appear here as you use the workspace.')}</section>`}
function settings(){return header('Make this workspace yours.','Preferences and local data controls.')+`<div class="settings"><form class="panel panel-pad" id="settings-form"><h3>Workspace preferences</h3><div class="section-gap">${field('Workspace name','name',state.settings.name,'text','maxlength="40"')}${field('Default disclosure expiry · minutes','expiry',state.settings.expiry,'number','min="1" max="1440" step="1"')}</div><label class="rule"><div>Hide amounts<small>Masks monetary values on screen. Stored records remain readable.</small></div><input type="checkbox" name="hide" ${state.settings.hide?'checked':''}></label><div class="section-gap"><button class="button primary">Save preferences</button></div></form><section class="panel panel-pad"><h3>Connections & data</h3><div class="export-row"><div><b>Wallet & settlement</b><p>NEAR Intents and Chain Signatures adapters are not connected.</p></div><span class="badge">NOT CONNECTED</span></div><div class="export-row"><div><b>Export workspace</b><p>Download all sandbox records as a JSON file.</p></div>${button('↓ Export','export','secondary')}</div><div class="export-row"><div><b>Reset sandbox</b><p>Remove this workspace’s saved requests, drafts, and preferences.</p></div>${button('Reset data','reset','secondary')}</div></section></div>`}
function render(){route=location.hash.slice(1)||'overview';if(route==='policies')route='agents';if(!names[route])route='overview';$('#crumb').textContent=names[route];$('#privacy').setAttribute('aria-label',state.settings.hide?'Show amounts':'Hide amounts');$('#nav').innerHTML=Object.keys(names).map(n=>`<a href="#${n}" class="${route===n?'active':''}" ${route===n?'aria-current="page"':''}>${icon(n)}${names[n]}${n==='approvals'&&state.payments.some(p=>p.status==='awaiting')?`<span class="count">${state.payments.filter(p=>p.status==='awaiting').length}</span>`:''}</a>`).join('');$('#main').innerHTML=({overview,payments,treasury,approvals,agents,proofs,activity,settings}[route])();bindForms()}
function open(title,body,callback,label='Save'){submit=callback;$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#form-error').textContent='';$('#modal-submit').textContent=label;$('#modal').showModal()}
const validAccount=s=>/^[a-z0-9]+(?:[._-][a-z0-9]+)*$/.test(s)&&s.length>=2&&s.length<=64;
const amount=v=>{const n=Number(v);if(!/^\d+(?:\.\d{1,2})?$/.test(v)||!Number.isFinite(n)||n<=0)throw Error('Enter a positive amount with at most two decimal places.');return n};
function action(a){if(names[a]){location.hash=a;return}if(a==='noop'){toast('Wallet connection is not available yet.');return}if(a==='payment'){open('New payment request',`<div class="notice">Requests are evaluated against the policy you set. No wallet or settlement connection is active.</div>${field('Counterparty','to','')}<div class="form-grid">${field('Amount · USDC','amount','','number','min="0.01" step="0.01"')}<label class="field">Asset / network<select disabled><option>USDC / NEAR</option></select></label></div>${field('Payment note','note','','text','maxlength="120"')}`,f=>{if(!state.policy.enabled)throw Error('Configure and enable a payment policy first.');let to=f.get('to').trim(),n=amount(f.get('amount'));if(!validAccount(to))throw Error('Enter a valid NEAR account.');let result=evaluatePayment(state.policy,{amount:n,counterparty:to},Math.round(spent()*100)/100);if(!result.allowed)throw Error(result.reason);state.payments.unshift({id:uid(),to,amount:n,note:f.get('note').trim(),at:now(),status:result.needsApproval?'awaiting':'ready'});log('Payment requested',`${to} · ${result.needsApproval?'review required':'policy passed'}`);return 'Payment request saved locally. No funds moved.'},'Create request')}
if(a==='payroll')open('Prepare a payroll batch',`${field('Batch name','name','','text','maxlength="80"')}<label class="field">Recipients & USDC amounts<textarea required name="rows" placeholder="recipient.near, 250.00"></textarea><small>One recipient,amount per line. Drafts cannot settle until wallet and payroll integrations are connected.</small></label>`,f=>{let lines=f.get('rows').trim().split('\n');if(lines.length>100)throw Error('Limit each draft to 100 recipients.');let rows=lines.map((line,i)=>{const parts=line.split(',').map(v=>v.trim());if(parts.length!==2||!validAccount(parts[0]))throw Error(`Check the account and amount on line ${i+1}.`);return {recipient:parts[0],amount:amount(parts[1])}});let total=Math.round(rows.reduce((n,r)=>n+r.amount,0)*100)/100;state.batches.unshift({id:uid(),name:f.get('name').trim(),rows,total,at:now()});log('Payroll drafted',`${rows.length} recipients`);return 'Payroll draft saved locally.'},'Save payroll draft');
if(a==='proof'){if(!state.policy.proofs){toast('Configure disclosure drafts in Agent controls first.');return}open('New disclosure draft',`<label class="field">Fact category<select name="type"><option>Balance threshold</option><option>Payment receipt</option><option>Payroll total</option><option>Agent spending limit</option></select></label>${field('Statement to prepare','fact','','text','maxlength="200"')}${field('Named reader · NEAR account','reader','')}${field('Expires in · minutes','minutes',state.settings.expiry,'number','min="1" max="1440" step="1"')}<p class="muted">Statements are user-entered and unverified. No cryptographic proof is generated.</p>`,f=>{let reader=f.get('reader').trim(),minutes=Number(f.get('minutes'));if(!validAccount(reader))throw Error('Enter a valid reader account.');if(!Number.isInteger(minutes)||minutes<1||minutes>1440)throw Error('Expiry must be between 1 and 1,440 minutes.');state.proofs.unshift({id:uid(),type:f.get('type'),fact:f.get('fact').trim(),reader,expiresAt:new Date(Date.now()+minutes*60000).toISOString(),at:now(),status:'draft'});log('Disclosure drafted',`Reader: ${reader}`);return 'Disclosure draft saved locally.'},'Save draft')}
if(a.startsWith('approve:')||a.startsWith('reject:')){let [kind,id]=a.split(':'),p=state.payments.find(p=>p.id===id);if(!p||p.status!=='awaiting')return;p.status=kind==='approve'?'ready':'rejected';log(kind==='approve'?'Approval simulated':'Request rejected',p.to);notify(kind==='approve'?'Approval simulated. Settlement remains disconnected.':'Request rejected; reserved budget released.')}
if(a.startsWith('revoke:')){let p=state.proofs.find(p=>p.id===a.slice(7));if(p){p.status='revoked';log('Disclosure revoked',p.reader);notify('Draft revoked.')}}
if(a==='export'){const payload={...state,exportedAt:now(),disclaimer:'Local sandbox. Plaintext, unverified records. No real funds or cryptographic proofs.'};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`scrim-workspace-${today()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Workspace export downloaded.')}
if(a==='reset')open('Reset this sandbox?',`<p class="muted">This removes all saved requests, batches, disclosures, activity, and preferences from this browser. Export first if you want a copy.</p>`,()=>{state=initial();return 'Sandbox reset.'},'Reset sandbox');}
function bindForms(){const policy=$('#policy-form');if(policy)policy.onsubmit=e=>{e.preventDefault();try{const f=new FormData(policy),daily=amount(f.get('dailyLimit')),per=amount(f.get('perPaymentLimit')),threshold=amount(f.get('approvalThreshold')),accounts=f.get('approved').split('\n').map(s=>s.trim()).filter(Boolean);if(per>daily)throw Error('Per-payment cap cannot exceed the daily cap.');if(threshold>per)throw Error('Approval threshold cannot exceed the per-payment cap.');if(daily<spent())throw Error('Daily cap cannot be lower than today’s reserved requests.');if(!accounts.length||accounts.some(s=>!validAccount(s)))throw Error('Enter at least one valid approved NEAR account.');state.policy={dailyLimit:daily,perPaymentLimit:per,approvalThreshold:threshold,approvedCounterparties:[...new Set(accounts)],enabled:f.has('enabled'),proofs:f.has('proofs')};log('Policy updated','Payment policy');notify('Agent policy saved.')}catch(err){$('#policy-error').textContent=err.message}};const settingsForm=$('#settings-form');if(settingsForm)settingsForm.onsubmit=e=>{e.preventDefault();const f=new FormData(settingsForm);state.settings={name:'',expiry:Number(f.get('expiry')),hide:f.has('hide')};log('Preferences updated','Workspace settings');notify('Preferences saved.')}}
$('#modal-form').onsubmit=e=>{e.preventDefault();try{let msg=submit(new FormData(e.currentTarget));$('#modal').close();notify(msg)}catch(err){$('#form-error').textContent=err.message}};
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(b)action(b.dataset.action);if(e.target.closest('[data-close]'))$('#modal').close();let tab=e.target.closest('[data-filter]');if(tab){filter=tab.dataset.filter;render()}});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;let pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}});
$('#privacy').onclick=()=>{state.settings.hide=!state.settings.hide;save();render()};$('#menu').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open))};window.addEventListener('hashchange',()=>{filter='all';search='';$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');render();window.scrollTo(0,0)});setInterval(()=>{if(route==='proofs'&&!$('#modal').open)render()},30000);render();
